\label{lem:cox-population-score}
Fix a transition $\ell=(j,k)$.  Suppose the correct Cox model
\eqref{eq:cox-main-transition-model} holds, the baseline cumulative hazard is finite, and the
risk functions have the boundedness, measurability, and fixed-$u$
$\beta$-continuity properties proved in
Lemma~\ref{lem:cox-risk-regularity}.  Suppose also that the minimal information
condition Assumption~\ref{ass:cox-main-primitives}\ref{cxmain:information} holds.  Then:
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item the population score is centered at the truth,
$U_\ell(\beta_{\ell,0})=0;$
\item the population score is differentiable on a possibly smaller open convex
neighborhood $\mathcal B_\ell$ of $\beta_{\ell,0}$, and
\begin{equation}
\label{eq:cox-population-score-derivative}
    \dot U_\ell(\beta)
    =-
    \int_{(0,\tau]}
    V_\ell(\beta,u)\,s_{\ell,0}(u)
    \,d\Lambda_{0,\ell,0}(u);
\end{equation}
\item consequently,
$-\dot U_\ell(\beta_{\ell,0})=I_\ell,$
where $I_\ell$ is the matrix in Assumption~\ref{ass:cox-main-primitives}\ref{cxmain:information};
\item  and
\begin{equation}
\label{eq:cox-local-information-bound}
    \sup_{\beta\in\mathcal B_\ell}
    \|\dot U_\ell(\beta)-\dot U_\ell(\beta_{\ell,0})\|
    \le \iota_\ell/4 .
\end{equation}
\end{enumerate}

\label{lem:cox-denominator-bounds}
Let $W_i(u)=Y_{j,i}(u)e^{\beta_0^\top X_i}$,
$S_n(u)=n^{-1}\sum_iW_i(u)$, $s(u)=E\{W_i(u)\}$, and
$J_n(u)=\mathbf 1\{S_n(u)>0\}$.  Suppose $\|X\|\le K$ and
$\|\beta_0\|\le R$.  Then there is a constant $C$, depending only on
$(K,R)$, such that for all $u$ and all $n$,
\begin{align}
\label{eq:cox-denominator-zero}
s(u)\Pr\{S_n(u)=0\}&\le Cn^{-1}, \\
\label{eq:cox-denominator-ratio}
E\left[
S_n(u)\left\{\frac{s(u)J_n(u)}{S_n(u)}-1\right\}^2
\right]&\le Cn^{-1}, \\
\label{eq:cox-denominator-inverse}
E\left[\frac{s(u)J_n(u)}{S_n(u)}\right]&\le C, \\
\label{eq:cox-denominator-inverse-risk}
E\left[\frac{J_n(u)}{S_n(u)}\right]&\le
C\,\frac{\mathbf 1\{s(u)>0\}}{s(u)}, \\
\label{eq:cox-denominator-weighted-ratio}
E\left[
s(u)\left\{\frac{s(u)J_n(u)}{S_n(u)}-1\right\}^2
\right]&\le Cn^{-1} .
\end{align}
Moreover, for each integer $m\ge1$ there is a constant $C_m$, depending
only on $(m,K,R)$, such that
\begin{align}
\label{eq:cox-denominator-moment-ratio}
E\left[\left\{\frac{s(u)J_n(u)}{S_n(u)}\right\}^m\right]&\le C_m, \\
\label{eq:cox-denominator-moment-weighted}
E\left[\frac{s(u)^mJ_n(u)}{S_n(u)^{m-1}}\right]&\le C_m s(u), \\
\label{eq:cox-denominator-moment-inverse}
E\left[\frac{s(u)^mJ_n(u)}{S_n(u)^{m}}\right]&\le C_m\,\mathbf 1\{s(u)>0\}.
\end{align}

\label{lem:cox-empirical-score}
Under Assumption~\ref{ass:cox-main-primitives}\ref{cxmain:bounded}--\ref{eq:cox-main-source-support}, for each
transition $\ell\in\mathcal J$,
\begin{equation}
\label{eq:cox-score-at-truth}
    \|U_{\ell,n}(\beta_{\ell,0})\|=O_p(n^{-1/2}),
\end{equation}
and
\begin{equation}
\label{eq:cox-score-derivative-uniform}
    \mathcal D_{\ell,n}:=
    \sup_{\beta\in\mathcal B_\ell}
    \|\dot U_{\ell,n}(\beta)-\dot U_\ell(\beta)\|=o_p(1).
\end{equation}

\label{lem:breslow-rates}
Under Assumption~\ref{ass:cox-main-primitives}, for each transition $\ell\in\mathcal J$,
\begin{align}
\label{eq:breslow-sup-rate}
\sup_{0\le t\le\tau}
|\widehat\Lambda_{0,\ell}(t)-\Lambda_{0,\ell,0}(t)|&=O_p(n^{-1/2}), \\
\label{eq:breslow-squared-jumps}
\sum_{0<u\le\tau}\{\Delta\widehat\Lambda_{0,\ell}(u)\}^2&=O_p(n^{-1}).
\end{align}

\label{lem:cox-risk-mean-replacement}
Fix a transition $\ell=(j,k)$, write $\beta_0=\beta_{\ell,0}$,
$s_0(u)=s_\ell^{(0)}(\beta_0,u)$, and let $h$ be bounded and deterministic.
Under Assumption~\ref{ass:cox-main-primitives},
\begin{equation}
\label{eq:cox-risk-mean-replacement}
\int_0^{\tau}s_0(u)h(u)
\{\bar Z_{\ell,n}(\beta_0,u)-\bar z_\ell(\beta_0,u)\}
\,d\Lambda_{0,\ell,0}(u)=O_p(n^{-1/2}).
\end{equation}
The same conclusion holds coordinatewise after multiplying the integrand by any
fixed bounded coordinate of $X$.

\label{lem:cox-self-normalized-equicontinuity}
Fix a transition $\ell$ and a bounded deterministic function $h$.  Let
$p_\ell=\dim(\beta_{\ell,0})$, which is fixed by
Assumption~\ref{ass:cox-main-primitives}\ref{cxmain:bounded}.  For every fixed $M<\infty$,
\begin{equation}
\label{eq:selfnorm-beta-equicontinuity}
\sup_{\|\beta-\beta_{\ell,0}\|\le Mn^{-1/2}}
\left|
\int_0^{\tau}h(u)
\left\{
\frac{s_{\ell,0}(u)J_{\ell,n}(u)}{S_{\ell,n}^{(0)}(\beta,u)}-
\frac{s_{\ell,0}(u)J_{\ell,n}(u)}{S_{\ell,n}^{(0)}(\beta_{\ell,0},u)}
\right\}
 d\bar M_{\ell,0}^{\beta}(u)
\right|=O_p(n^{-1}).
\end{equation}

Write $\beta_0=\beta_{\ell,0}$, $S_n(\beta,u)=S_{\ell,n}^{(0)}(\beta,u)$, $s_0=s_{\ell,0}$, and $J=J_{\ell,n}$. On the shrinking ball
$B_n(M)=\{\beta:\|\beta-\beta_0\|\le Mn^{-1/2}\}$, define
$$M_n(\beta)=\int_0^{\tau}h(u) \left\{\frac{s_0(u)J(u)}{S_n(\beta,u)}- \frac{s_0(u)J(u)}{S_n(\beta_0,u)}\right\} d\bar M_{\ell,0}^{\beta}(u).$$


For $\beta,\beta'\in B_n(M)$, the mean-value theorem and bounded covariates give,
$\left|\frac1{S_n(\beta,u)}-\frac1{S_n(\beta',u)}\right| \le C\|\beta-\beta'\|\frac1{S_n(\beta_0,u)}$,
on $J=1$ .
Indeed, $S_n(\beta,u)/S_n(\beta_0,u)$ lies between $e^{-K\|\beta-\beta_0\|}$ and $e^{K\|\beta-\beta_0\|}$ on this ball.
With
$g_{\beta,\beta'}(u)=h(u)s_0(u)J(u) \left\{\frac1{S_n(\beta,u)}-\frac1{S_n(\beta',u)}\right\}$,
we therefore have
\begin{equation}
\label{eq:selfnorm-lipschitz-bound}
|g_{\beta,\beta'}(u)|
\le C\|\beta-\beta'\|\,\frac{s_0(u)J(u)}{S_n(\beta_0,u)}.
\end{equation}

Let
$\Delta_n(\beta,\beta')=M_n(\beta)-M_n(\beta') =\int g_{\beta,\beta'}(u)d\bar M_{\ell,0}^{\beta}(u)$.
For an integer $r>p_\ell+2$, the Burkholder--Davis--Gundy inequality for purely
discontinuous square-integrable martingales gives
\begin{equation}
\label{eq:selfnorm-bdg-bound}
E|\Delta_n(\beta,\beta')|^{2r}
\le C_r E\{\langle\Delta_n(\beta,\beta')\rangle(\tau)^r\}
+C_rE\sum_{u\le\tau}|\Delta\Delta_n(\beta,\beta';u)|^{2r}.
\end{equation}
The predictable quadratic variation satisfies
$\langle\Delta_n(\beta,\beta')\rangle(\tau) \le \frac1n\int_0^{\tau}g_{\beta,\beta'}(u)^2 S_n(\beta_0,u)d\Lambda_{0,\ell,0}(u).$
Apply \eqref{eq:selfnorm-lipschitz-bound}, Jensen's inequality for the finite measure
$s_0(u)d\Lambda_{0,\ell,0}(u)$, and \eqref{eq:cox-denominator-moment-ratio} to obtain
\begin{equation}
\label{eq:selfnorm-bracket-moment}
E\{\langle\Delta_n(\beta,\beta')\rangle(\tau)^r\}
\le C_r n^{-r}\|\beta-\beta'\|^{2r}.
\end{equation}
For the jump contribution, Lemma~\ref{lem:cox-no-ties} gives
$\Delta\Lambda_{0,\ell,0}(u)=0$. Thus the compensator $S_n(\beta_0,u)d\Lambda_{0,\ell,0}(u)$ is continuous and
$\Delta\bar M_{\ell,0}^{\beta}(u)=\Delta\mathbb P_{\mathrm{tr},n} N_\ell(u).$
At each transition-$\ell$ jump time, at most one subject jumps, so
$\Delta\mathbb P_{\mathrm{tr},n} N_\ell(u)\le n^{-1}$. Consequently,
\[
\sum_{u\le\tau}|\Delta\Delta_n(\beta,\beta';u)|^{2r} \le n^{-2r}\sum_{i=1}^n\int_0^{\tau} |g_{\beta,\beta'}(u)|^{2r}\,dN_{\ell,i}(u).
\]
Taking expectations with the predictable compensator of $N_{\ell,i}$ yields
\[
E\sum_{u\le\tau}|\Delta\Delta_n(\beta,\beta';u)|^{2r}
\le n^{-2r+1}
\int E\{|g_{\beta,\beta'}(u)|^{2r}S_n(\beta_0,u)\}
    d\Lambda_{0,\ell,0}(u).
\]
By \eqref{eq:selfnorm-lipschitz-bound} and \eqref{eq:cox-denominator-moment-weighted},
\begin{align}
\label{eq:selfnorm-jump-moment}
E\sum_{u\le\tau}|\Delta\Delta_n(\beta,\beta';u)|^{2r}
&\le C_r n^{-2r+1}\|\beta-\beta'\|^{2r}
\int s_0(u)d\Lambda_{0,\ell,0}(u) \\
&\le C_r n^{-r}\|\beta-\beta'\|^{2r}. \notag
\end{align}
The final inequality uses $n^{-2r+1}\le n^{-r}$ for $r\ge1$. Combining
\eqref{eq:selfnorm-bdg-bound}--\eqref{eq:selfnorm-jump-moment} gives
\begin{equation}
\label{eq:selfnorm-increment-moment}
E|M_n(\beta)-M_n(\beta')|^{2r}
\le C_r n^{-r}\|\beta-\beta'\|^{2r}.
\end{equation}
Taking $\beta'=\beta_0$ and using $\|\beta-\beta_0\|\le Mn^{-1/2}$ gives
\begin{equation}
\label{eq:selfnorm-pointwise-moment}
E|M_n(\beta)|^{2r}\le C_r n^{-2r}.
\end{equation}

For the uniform bound, apply the dyadic-net argument used in the proof of
Lemma~\ref{lem:cox-self-normalized-ratios}, now on $B_n(M)$.
A $2^{-m}Mn^{-1/2}$-net has cardinality at most $C2^{mp_\ell}$.
The paths are continuous in $\beta$, since $S_n(\beta,u)$ is smooth
and its reciprocal is used only where $J=1$.
For the successive net increments, \eqref{eq:selfnorm-increment-moment} and
Markov's inequality give
\[
\Pr\left\{\max_{\text{level }m\text{ pairs}}
|M_n(t)-M_n(s)|>An^{-1}2^{-m/2}\right\}
\le C_rA^{-2r}2^{-m(r-p_\ell)}.
\]
The right-hand side is summable because $r>p_\ell+2$.
The coarse-net contribution is $O_p(n^{-1})$ by
\eqref{eq:selfnorm-pointwise-moment}, and the remaining thresholds sum to
$CAn^{-1}$. Thus $\sup_{\beta\in B_n(M)}|M_n(\beta)|=O_p(n^{-1})$,
proving \eqref{eq:selfnorm-beta-equicontinuity} .

\label{lem:cox-row-stabilization}
Under Assumption~\ref{ass:cox-main-primitives}, the stabilized Cox plug-in satisfies, uniformly
over covariate values in the support of $X$,
\begin{align}
\label{eq:cox-conditional-hazard-sup}
\|\widehat A_n(\cdot\mid x)-A_0(\cdot\mid x)\|_{\infty,\tau}&=O_p(n^{-1/2}), \\
\label{eq:cox-conditional-hazard-jumps}
[\widehat A_n(\cdot\mid x)-A_0(\cdot\mid x)]_{\Delta,2,\tau}&=O_p(n^{-1}).
\end{align}
Moreover, $\widehat A_n(\cdot\mid x)\in\mathscr A_{\tau}$ pathwise for every
$x$.  The only total-variation bound asserted in this lemma is the
bound for the artificial row-stabilization correction $\widehat A_n-\bar A_n$:
\begin{equation}
\label{eq:cox-row-stabilization-variation}
\sum_{\ell\in\mathcal J}\sup_x
\left|\widehat A_{\ell,n}(\cdot\mid x)-\bar A_{\ell,n}(\cdot\mid x)\right|_{\mathrm{TV},\tau}
=O_p(n^{-1}).
\end{equation}

\label{thm:cox-breslow-rates}
Under Assumption~\ref{ass:cox-main-primitives}, the explicit coefficient and
baseline-hazard estimators above satisfy the corresponding rates stated
in Proposition~\ref{prop:cox-main-regime}. For each $\ell\in\mathcal J$ and fixed
bounded deterministic $h_\ell$, they also satisfy
\begin{equation}
\label{eq:cox-source-weighted-rate}
\int_0^{\tau}s_{\ell,0}(u)h_\ell(u)
\,d\{\widehat\Lambda_{0,\ell}-\Lambda_{0,\ell,0}\}(u)=O_p(n^{-1/2}).
\end{equation}
For the row-stabilized conditional hazards specified above,
\begin{equation}
\label{eq:cox-plugin-rate}
\widehat\mu_{n,m}^{\mathrm{plug}}(\tau)-\mu_\tau(A_0)
=O_p(m^{-1/2}+n^{-1/2}).
\end{equation}
In particular, the rate is $O_p(n^{-1/2})$ when $m\asymp n$.
No condition of the form $\inf_{u\le\tau}s_{12,0}(u)>0$ is imposed.

\label{lem:cox-standardized-derivative-rate}
Recall that $\dot\mu_{\tau,A_0}[\widehat A_n-A_0](x)$ is the conditional
RMST derivative from Lemma~\ref{lem:rmst-hazard-derivative}, evaluated at the true
conditional hazard $A_0(\cdot\mid x)$ in the direction
$\widehat A_n(\cdot\mid x)-A_0(\cdot\mid x)$.   Under Assumption~\ref{ass:cox-main-primitives},
\begin{equation}
\label{eq:cox-standardized-derivative-rate}
\dot\mu_{\tau,A_0}^{\mathrm{std}}[\widehat A_n-A_0]=O_p(n^{-1/2}).
\end{equation}

\label{thm:plugin-rmst-expansion}
Assume the conditional-hazard and sample-splitting setup at the beginning of
Section~\ref{app:covariate-proofs}, with the product-integral notation of
Section~\ref{sec:setup-notation}.  Let $\widehat A_n$ be $\mathcal D_{\mathrm{tr},n}$-measurable and let the evaluation
sample be independent of $\mathcal D_{\mathrm{tr},n}$.  Assume that, with probability
tending to one,
$A_0(\cdot\mid x),\widehat A_n(\cdot\mid x)\in\mathscr A_{\tau} \quad\text{for }P_X\text{-a.e. }x,$
and that, for deterministic $a_n,b_n\downarrow0$,
\begin{equation}
\label{eq:plugin-rate-assumptions}
    P_X\{\kappa_n(X)^2\}=O_p(a_n^2),
    \qquad
    P_X\{\omega_n(X)\}=O_p(b_n).
\end{equation}
Then
\begin{equation}
\label{eq:plugin-rate-expansion}
\widehat\mu_{n,m}^{\mathrm{plug}}(\tau)-\mu_\tau(A_0)
=
(\mathbb P_{\mathrm{ev},m}-P_X)\mu_{A_0}
+
\dot\mu_{\tau,A_0}^{\mathrm{std}}[\widehat A_n-A_0]
+
O_p\{b_n+m^{-1/2}a_n\}.
\end{equation}
Moreover,
\begin{equation}
\label{eq:plugin-derivative-bound}
\left|\dot\mu_{\tau,A_0}^{\mathrm{std}}[\widehat A_n-A_0]\right|
=O_p(a_n+b_n),
\end{equation}
and hence
\begin{equation}
\label{eq:plugin-upper-rate}
\widehat\mu_{n,m}^{\mathrm{plug}}(\tau)-\mu_\tau(A_0)
=
O_p(m^{-1/2}+a_n+b_n).
\end{equation}
In particular, if $m\asymp n$, $a_n=n^{-1/2}$, and $b_n=n^{-1}$, then
$\widehat\mu_{n,m}^{\mathrm{plug}}(\tau)-\mu_\tau(A_0) = O_p(n^{-1/2}).$

Condition on $\mathcal D_{\mathrm{tr},n}$ and put
$g_n(x)=\mu_{\widehat A_n}(\tau\mid x)-\mu_{A_0}(\tau\mid x)$.
The evaluation observations are conditionally independent with common law $P_X$.
On the admissibility event in the theorem, Lemma~\ref{lem:rmst-hazard-derivative}
gives, for $P_X$-almost every $x$,
\begin{equation}
\label{eq:plugin-pointwise-expansion}
g_n(x)=\dot\mu_{\tau,A_0}[\widehat A_n-A_0](x)+r_n(x),
\end{equation}
where $|r_n(x)|\le\tau\omega_n(x)$ and $|g_n(x)|\le2\tau\kappa_n(x)$.
Consequently, $P_X|r_n|\le\tau P_X\omega_n$ and
$P_Xg_n^2\le4\tau^2P_X\kappa_n^2$, which also justify the expectations below.
Adding and subtracting the population and evaluation means yields
\begin{align}
\label{eq:plugin-main-expansion}
\widehat\mu_{n,m}^{\mathrm{plug}}(\tau)-\mu_\tau(A_0)
&=(\mathbb P_{\mathrm{ev},m}-P_X)\mu_{A_0}
 +\dot\mu_{\tau,A_0}^{\mathrm{std}}[\widehat A_n-A_0]+R_{n,m},\\
\label{eq:plugin-remainder}
R_{n,m}&=P_Xr_n+(\mathbb P_{\mathrm{ev},m}-P_X)g_n.
\end{align}
Applying \eqref{eq:conditional-evaluation-variance} conditionally on the
training sample, $(\mathbb P_{\mathrm{ev},m}-P_X)g_n$ has mean zero and
\begin{equation}
\label{eq:plugin-conditional-variance}
E\!\left[\left.\{(\mathbb P_{\mathrm{ev},m}-P_X)g_n\}^{2}\right|\mathcal D_{\mathrm{tr},n}\right]
\le m^{-1}P_Xg_n^2
\le 4\tau^2m^{-1}P_X\kappa_n^2.
\end{equation}
Under \eqref{eq:plugin-rate-assumptions}, conditional Chebyshev's inequality
therefore gives $(\mathbb P_{\mathrm{ev},m}-P_X)g_n=O_p(m^{-1/2}a_n)$, while
$P_Xr_n=O_p(b_n)$. Hence
$R_{n,m}=O_p\{b_n+m^{-1/2}a_n\}$,
proving \eqref{eq:plugin-rate-expansion}.

For the derivative, \eqref{eq:plugin-pointwise-expansion} and Cauchy--Schwarz imply
\begin{equation}
\label{eq:plugin-derivative-rate}
\left|\dot\mu_{\tau,A_0}^{\mathrm{std}}[\widehat A_n-A_0]\right|
\le 2\tau\{P_X\kappa_n^2\}^{1/2}+\tau P_X\omega_n
=O_p(a_n+b_n).
\end{equation}
This proves \eqref{eq:plugin-derivative-bound}. Since
$0\le\mu_{A_0}(\tau\mid X)\le\tau$, we also have
$(\mathbb P_{\mathrm{ev},m}-P_X)\mu_{A_0}=O_p(m^{-1/2})$.
Combining these bounds in \eqref{eq:plugin-main-expansion}, and using $a_n\downarrow0$,
gives $\widehat\mu_{n,m}^{\mathrm{plug}}-\mu_\tau(A_0)
=O_p(m^{-1/2}+a_n+b_n)$, as required in
\eqref{eq:plugin-upper-rate}. The special case follows by
substituting $m\asymp n$, $a_n=n^{-1/2}$, and $b_n=n^{-1}$.

\label{thm:onestep-exact-bias}
Assume the conditional-hazard and sample-splitting setup at the beginning of
Section~\ref{app:covariate-proofs}, with the product-integral conventions of
Section~\ref{sec:setup-notation}.  Assume independent evaluation sampling, conditional independent censoring, and
$\inf_{u,x}G(u-\mid x)>0$.  Conditionally on $\mathcal D_{\mathrm{tr},n}$, assume
that $\widehat A_n$ is measurable, that
$A_0(\cdot\mid X),\widehat A_n(\cdot\mid X)\in\mathscr A_{\tau}$ a.s., and
that the fitted weights $\widehat H_{\ell,n}$ are predictable and square
integrable.  Suppose also that
\[
\sum_{\ell\in\mathcal J}
  P\int_0^{\tau}
  \{|\widehat H_{\ell,n}|+|H_{\ell,0}|\}
  Y_{j(\ell)}
  \,d|\widehat A_{\ell,n}-A_{\ell,0}| <\infty,
  \qquad
  P_X\omega_{\mathrm{PI}}\{A_0,\widehat A_n\}<\infty .
\]
Then
\begin{align}
\label{eq:onestep-decomposition}
  &\widehat\mu_{n,m}^{\textsf{os}}-\mu_\tau(A_0)
  =(\mathbb P_{\mathrm{ev},m}-P)\widehat\psi_n+B_n, \\
  \label{eq:onestep-bias}
  &B_n
  =
  \sum_{\ell\in\mathcal J}P\int_0^{\tau}
  \{H_{\ell,0}(u,X)-\widehat H_{\ell,n}(u,X)\}Y_{j(\ell)}(u)
  \,d\{\widehat A_{\ell,n}-A_{\ell,0}\}(u\mid X)
  +P_X r_n,
\end{align}
where
$|r_n(x)| \le \tau \omega_{\mathrm{PI}}\{A_0(\cdot\mid x),\widehat A_n(\cdot\mid x)\}.$
Hence the linear plug-in term cancels exactly.  Equivalently, for the hazard-induced weights that use the fitted censoring survival $\widehat G_n$,
\begin{align}
\label{eq:onestep-censoring-bias}
  B_n
  &=
  \sum_{\ell\in\mathcal J}P_X\int_0^\tau
  P^{A_0}_{j(\ell)}(u-\mid X)
  \{V^{\widehat A_n}_{k(\ell)}(u,\tau\mid X)-V^{\widehat A_n}_{j(\ell)}(u,\tau\mid X)\} \\
&\hspace{1.0in}\times
  \left\{1-\frac{G(u-\mid X)}{\widehat G_n(u-\mid X)}\right\}
  \,d\{\widehat A_{\ell,n}-A_{\ell,0}\}(u\mid X). \notag
\end{align}
In particular, if $\widehat G_n=G$, the conditional mean of the hazard-induced one-step summand equals $\mu_\tau(A_0)$ for every bounded admissible fitted transition law $\widehat A_n$.

\label{lem:rmst-weight-variation}
Fix a covariate value $x$.  Let $A(\cdot\mid x)\in\mathscr A_{\tau}$ and
assume the censoring survival satisfies $G(u-\mid x)\ge g_0>0$ and is
nonincreasing in $u$.  Let $H_{\ell,A}$ be the RMST martingale weights induced by
$A$, as in \eqref{eq:rmst-weight-definition}.  Then
\begin{equation}
\label{eq:rmst-weight-variation}
\max_{\ell\in\mathcal J}
\left[
\sup_{u\le\tau}|H_{\ell,A}(u,x)|
+
\operatorname{pvar}\{H_{\ell,A}(\cdot,x);[0,\tau]\}
\right]
\le C_{\tau,g_0}\{1+|A(\cdot\mid x)|_{\tau}\} .
\end{equation}
Consequently, if $Y_j$ is an illness--death at-risk indicator, then
\begin{equation}
\label{eq:weighted-risk-variation}
\operatorname{pvar}\{Y_j(\cdot)H_{\ell,A}(\cdot,x);[0,\tau]\}
+
\sup_{u\le\tau}|Y_j(u)H_{\ell,A}(u,x)|
\le C_{\tau,g_0}\{1+|A(\cdot\mid x)|_{\tau}\} .
\end{equation}

Work on $\mathcal E_N$. Since $\Pr(\mathcal E_N)\to1$, the stochastic orders established there
also hold unconditionally. Constants may depend on $(\tau,g_0,M,K,\underline\pi, \overline\pi)$, but not on
$N$ or the realized training samples. For fold $k$, condition
on $\mathcal D_{-k}$. The observations in $I_k$ are independent of $(\widehat A^{(-k)},\widehat G^{(-k)})$
and have common law $P$. Pointwise in $x$, write
$A=A_0(\cdot\mid x),\qquad B_k=\widehat A^{(-k)}(\cdot\mid x),\qquad D_k=B_k-A .$

Let $\widehat\psi_{-k}$ be the fold-specific summand and put
$B_{k,N}=P\widehat\psi_{-k}-\mu_\tau$.
Apply \eqref{eq:onestep-censoring-bias} from
Theorem~\ref{thm:onestep-exact-bias} conditionally on $\mathcal D_{-k}$.
The fitted hazards and censoring law satisfy its measurability,
admissibility, positivity, and integrability requirements on $\mathcal E_N$;
bounded weights and hazard masses give the latter integrability.
The resulting exact identity is
\begin{align*}
B_{k,N}
&=\sum_{\ell\in\mathcal J}P_X\int_0^\tau
P^{A_0}_{j(\ell)}(u-\mid X)
\{V^{\widehat A^{(-k)}}_{k(\ell)}-V^{\widehat A^{(-k)}}_{j(\ell)}\}(u,\tau\mid X)\\
&\qquad\times\left\{1-\frac{G(u-\mid X)}{\widehat G^{(-k)}(u-\mid X)}\right\}
\,d\{\widehat A_\ell^{(-k)}-A_{\ell,0}\}(u\mid X).
\end{align*}
This cancellation uses the same fitted transition law in the fitted RMST,
residual weights, and compensator. In particular, $B_{k,N}=0$ when
$\widehat G^{(-k)}=G$, for every bounded admissible fitted transition law.

For part~(a), on $\mathcal E_N$ we have
$|W_{\ell,\widehat A^{(-k)}}(u,x)|\le 2\tau, \qquad P^{A_0}_{j(\ell)}(u-\mid x)\le1,$
and
$|dD_{k,\ell}| \le d\widehat A_{\ell}^{(-k)}+dA_{\ell,0}.$
Both hazard laws have total mass at most $M$, so
\begin{equation}
\label{eq:fold-bias-bound-crossfit}
\max_{1\le k\le K}|B_{k,N}|
\le C_{\tau,M}\max_{1\le k\le K}P_X\{\eta_{-k}(X)\}
=O_p(c_N).
\end{equation}
The last equality follows from Cauchy--Schwarz and
\eqref{eq:main-censoring-rate}.
Let $\mathbb P_{I_k}f=m_k^{-1}\sum_{i\in I_k}f(O_i)$. Adding and subtracting the foldwise means gives
\begin{equation}
\label{eq:crossfit-onestep-decomposition}
\widehat\mu_N^{\rm cf,os}-\mu_\tau
 =\sum_{k=1}^K\frac{m_k}{N}(\mathbb P_{I_k}-P)\widehat\psi_{-k}
+
\sum_{k=1}^K\frac{m_k}{N}B_{k,N}.
\end{equation}
On $\mathcal E_N$,
$0\le \widehat\mu_{-k}(X)\le\tau, \qquad |\widehat H_{\ell}^{(-k)}(u,X)|\le 4\tau/g_0,$
and
$$\sum_{\ell\in\mathcal J}\int_0^\tau Y_{j(\ell)}(u)d\widehat A_{\ell}^{(-k)}(u\mid X) \le |\widehat A^{(-k)}(\cdot\mid X)|_\tau\le M ,  \qquad \sum_{\ell\in\mathcal J}N_\ell(\tau)\le2.$$
Thus $|\widehat\psi_{-k}(O)|\le C_{\tau,g_0,M}$. Conditional on $\mathcal D_{-k}$,
$$E\{(\mathbb P_{I_k}-P)\widehat\psi_{-k}\mid\mathcal D_{-k}\}=0, \ \ E\left[\{(\mathbb P_{I_k}-P)\widehat\psi_{-k}\}^2\mid\mathcal D_{-k}\right] \le C m_k^{-1}.$$
Chebyshev's inequality gives $(\mathbb P_{I_k}-P)\widehat\psi_{-k}=O_p(m_k^{-1/2})$ in each fold. Since $K$ is
fixed and $m_k\asymp N$, the weighted sum of empirical terms in
\eqref{eq:crossfit-onestep-decomposition} is $O_p(N^{-1/2})$. Combining this with
\eqref{eq:fold-bias-bound-crossfit} proves \eqref{eq:main-os-rate-with-Ghat}.

For part~(b), apply the pointwise expansion and
conditional variance bound of Theorem~\ref{thm:plugin-rmst-expansion} separately in each
fold. Admissibility and bounded mass hold on $\mathcal E_N$, and
\eqref{eq:main-plugin-precise-rates} and the product-integral Lipschitz bound
give $\max_kP_X\kappa_{-k}^2=O_p(a_N^2)$ and
$\max_kP_X\omega_{-k}=O_p(b_N)$.
The exact decomposition is
\begin{align}
\label{eq:crossfit-plugin-decomposition}
\widehat\mu_N^{\rm cf,plug}(\tau)-\mu_\tau
&=(\mathbb P_N-P_X)\mu_{A_0}
+\sum_{k=1}^K\frac{m_k}{N}P_X\{\mu_{\widehat A^{(-k)}}-\mu_{A_0}\} \\
&\quad+
\sum_{k=1}^K\frac{m_k}{N}(\mathbb P_{I_k}-P_X)
\{\mu_{\widehat A^{(-k)}}-\mu_{A_0}\}. \notag
\end{align}
The first term is $O_p(N^{-1/2})$.
By \eqref{eq:plugin-pointwise-expansion} and \eqref{eq:plugin-derivative-rate},
each population mean difference in the second term is $O_p(a_N+b_N)$.
The conditional variance bound \eqref{eq:plugin-conditional-variance}
makes each foldwise empirical remainder $O_p(m_k^{-1/2}a_N)$.
Since $K$ is fixed and $m_k\asymp N$, their weighted sum is
$O_p(N^{-1/2}a_N)=o_p(N^{-1/2})$, proving \eqref{eq:main-plugin-rate}.
This uses separate foldwise conditional bounds and a finite sum,
not independence between the fold remainders.

For part~(c), impose the additional assumptions in that part and add and
subtract the true residual-RMST contrast:
\begin{align*}
B_{k,N}
&=T_{0,k}+T_{1,k}, \\
T_{0,k}
&=
\sum_{\ell\in\mathcal J}P_X\int_0^\tau
L_{\ell,0}(u,X)e_{G,-k}(u,X)\,dD_{k,\ell}(u\mid X), \\
T_{1,k}
&=
\sum_{\ell\in\mathcal J}P_X\int_0^\tau
P^{A_0}_{j(\ell)}(u-\mid X)
\{W_{\ell,\widehat A^{(-k)}}-W_{\ell,A_0}\}(u,X)
 e_{G,-k}(u,X)\,dD_{k,\ell}(u\mid X).
\end{align*}
By \eqref{eq:main-AG-transform-rate},
$\max_k|T_{0,k}|=O_p(a_Nc_N).$
The definition of $\kappa_{-k}$ gives
$\sup_{u\le\tau} |W_{\ell,\widehat A^{(-k)}}(u,x)-W_{\ell,A_0}(u,x)| \le C_\tau\kappa_{-k}(x)$.
Using the bounded-mass inequality
$\int_0^\tau |dD_{k,\ell}(u\mid x)| \le \widehat A_{\ell}^{(-k)}(\tau\mid x)+A_{\ell,0}(\tau\mid x) \le 2M$,
and Cauchy--Schwarz, we obtain
\begin{align*}
\max_k|T_{1,k}|
&\le
C_{\tau,M}\max_kP_X\{\kappa_{-k}(X)\eta_{-k}(X)\} \\
&\le
C_{\tau,M}\max_k
\{P_X\kappa_{-k}(X)^2\}^{1/2}
\{P_X\eta_{-k}(X)^2\}^{1/2}
=O_p(a_Nc_N).
\end{align*}
Consequently,
\begin{equation}
\label{eq:fold-bias-product-rate}
\max_{1\le k\le K}|B_{k,N}|=O_p(a_Nc_N).
\end{equation}

